 {name:'Eclipse Core',icon:'☯',desc:'The final relic binds the temple to the stars.',base:900000000000,growth:1.25,kind:'eps',power:65000000,visual:'<g class="pixel-glow" shape-rendering="crispEdges"><rect x="295" y="286" width="50" height="50" fill="#3a164f"/><rect x="302" y="279" width="36" height="64" fill="#a52be6"/><rect x="295" y="286" width="50" height="50" fill="#591f85"/><path d="M315 289h10v11h10v10h-10v10h-10v-10h-10v-10h10z" fill="#ff8ee7"/><rect x="316" y="303" width="8" height="8" fill="#fff2bd"/><rect x="281" y="306" width="8" height="4" fill="#f6b8ff"/><rect x="351" y="306" width="8" height="4" fill="#f6b8ff"/></g>'}
];

const SAVE_KEY='violet-temple-save-v1', PRESTIGE_AT=1_000_000, OFFLINE_CAP=8*60*60*1000;
const freshState=()=>({essence:0,levels:upgrades.map(()=>0),sparks:0,runEarned:0,last:Date.now()});
function loadState(){
 try{const raw=JSON.parse(localStorage.getItem(SAVE_KEY));if(!raw||!Array.isArray(raw.levels))return freshState();
  const s=freshState();s.essence=Math.max(0,Number(raw.essence)||0);s.sparks=Math.max(0,Math.floor(Number(raw.sparks)||0));s.runEarned=Math.max(0,Number(raw.runEarned)||0);
  s.levels=upgrades.map((_,i)=>Math.max(0,Math.floor(Number(raw.levels[i])||0)));s.last=Number(raw.last)||Date.now();return s;
 }catch(_){return freshState()}
}
let state=loadState(),soundOn=false,audioContext=null,toastTimer;
const $=id=>document.getElementById(id), shop=$('shopList'), featureLayer=$('features');
function fmt(value){
 if(!Number.isFinite(value))return '∞';if(value<0)return '-'+fmt(-value);
 if(value<1000)return value<10&&value%1?value.toFixed(1).replace(/\.0$/,''):Math.floor(value).toLocaleString('en-US');
 const suffix=['K','M','B','T','Qa','Qi','Sx','Sp','Oc','No','Dc'];let tier=Math.floor(Math.log10(value)/3)-1;
 if(tier<suffix.length){let n=value/Math.pow(1000,tier+1);return n.toFixed(1).replace(/\.0$/,'')+suffix[tier]}
 return value.toExponential(2).replace('+','');
}
const mult=()=>1+state.sparks*.05;
function rates(){let click=1,eps=0;upgrades.forEach((u,i)=>{if(!state.levels[i])return;const amount=u.power*state.levels[i];if(u.kind==='click')click+=amount;else eps+=amount});return {click:click*mult(),eps:eps*mult()}}
function costAt(i){return upgrades[i].base*Math.pow(upgrades[i].growth,state.levels[i])}
function buildShop(){
 shop.innerHTML='';upgrades.forEach((u,i)=>{const b=document.createElement('button');b.type='button';b.className='upgrade';b.dataset.index=i;b.innerHTML=`<span class="upgrade-icon" aria-hidden="true">${u.icon}</span><span class="upgrade-copy"><span class="upgrade-name">${u.name}</span><span class="upgrade-desc">${u.desc}<br><b class="effect-line"></b></span><span class="upgrade-level"></span></span><span class="upgrade-cost"></span>`;b.addEventListener('click',()=>buy(i));shop.appendChild(b)});
}
function render(){
 const r=rates();$('essence').textContent=fmt(state.essence);$('clickRate').textContent=fmt(r.click);$('eps').textContent=fmt(r.eps);$('totalRun').textContent=fmt(state.runEarned)+' earned this age';$('sparkCount').textContent=fmt(state.sparks);$('sparkBadge').textContent=fmt(state.sparks)+' spark'+(state.sparks===1?'':'s');$('multiplier').textContent=mult().toFixed(2)+'× essence power';
 const owned=state.levels.filter(n=>n>0).length;$('buildCount').textContent=(owned?'Awakened':'Unawakened')+' · '+owned+' / 25';$('shopCount').textContent=owned+' / 25 awakened';
 upgrades.forEach((u,i)=>{let b=shop.children[i],cost=costAt(i),level=state.levels[i];b.disabled=state.essence<cost;b.classList.toggle('affordable',state.essence>=cost);b.querySelector('.upgrade-cost').innerHTML=fmt(cost)+'<span class="upgrade-level">Cost</span>';b.querySelector('.upgrade-level').textContent='Owned · '+level;b.querySelector('.effect-line').textContent='+'+fmt(u.power)+' '+(u.kind==='click'?'Essence / click':'Essence / sec')+' per level';});
 const can=state.runEarned>=PRESTIGE_AT,grant=Math.floor(state.runEarned/PRESTIGE_AT);$('prestigeBtn').disabled=!can;$('prestigeBtn').textContent=can?'Rebirth · Gain '+fmt(grant)+' Divine Spark'+(grant===1?'':'s'):'Rebirth · Need '+fmt(Math.max(0,PRESTIGE_AT-state.runEarned))+' more earned';
 $('prestigeText').textContent=can?'Reset Essence and all temple relics for '+grant+' Divine Spark'+(grant===1?'':'s')+'. Each spark permanently adds 5% to click and idle Essence.':`Earn ${fmt(PRESTIGE_AT)} Essence this age to rebirth. Each spark permanently increases all Essence by 5%.`;
 renderFeatures();
}
function renderFeatures(){
 upgrades.forEach((u,i)=>{let g=document.getElementById('feature-'+i),level=state.levels[i];if(level>0){if(!g){g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='feature-'+i;g.classList.add('feature');g.innerHTML=u.visual;featureLayer.appendChild(g)}g.classList.add('on');g.style.opacity=String(Math.min(.72+Math.log2(level+1)*.08,1));g.setAttribute('aria-label',u.name+' level '+level);g.dataset.level=level;}else if(g){g.classList.remove('on');g.style.opacity='0'}});
}
function gain(amount){if(!(amount>0)||!Number.isFinite(amount))return;state.essence+=amount;state.runEarned+=amount}
function buy(i){const cost=costAt(i);if(state.essence+1e-9<cost)return;state.essence-=cost;state.levels[i]++;render();save();showToast(upgrades[i].name+' awakened!');}
function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1700)}
function save(){state.last=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('saveStatus').textContent='All progress saved'}catch(_){$('saveStatus').textContent='Saving unavailable'}}
function clickTemple(event){const r=rates();gain(r.click);render();if(soundOn)beep();const el=document.createElement('span');el.className='float-text';el.textContent='+'+fmt(r.click);const rect=$('templeClick').getBoundingClientRect();el.style.left=Math.max(12,Math.min(innerWidth-100,(event.clientX||rect.left+rect.width/2)-rect.left+12))+'px';el.style.top=Math.max(60,(event.clientY||rect.top+rect.height/2)-rect.top-8)+'px';$('templeClick').appendChild(el);setTimeout(()=>el.remove(),850)}
function beep(){try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='square';osc.frequency.value=660;gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.06);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.06)}catch(_){}}

