function beep(){try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='square';osc.frequency.value=660;gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.06);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.06)}catch(_){}}

$('templeClick').addEventListener('click',clickTemple);
$('prestigeBtn').addEventListener('click',()=>{
 if(state.runEarned<PRESTIGE_AT)return;const gainSparks=Math.floor(state.runEarned/PRESTIGE_AT);
 if(!confirm(`Rebirth now? You will lose ${fmt(state.essence)} Essence and all 25 upgrade levels, and gain ${fmt(gainSparks)} Divine Spark${gainSparks===1?'':'s'}.`))return;
 state.sparks+=gainSparks;state.essence=0;state.runEarned=0;state.levels=upgrades.map(()=>0);render();save();showToast('The sanctuary is reborn with '+gainSparks+' Divine Spark'+(gainSparks===1?'':'s')+'!');
});
$('resetBtn').addEventListener('click',()=>{
 if(!confirm('Erase all saved Essence, upgrades, and Divine Sparks? This cannot be undone.'))return;
 state=freshState();render();save();showToast('A new age begins.');
});
$('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').textContent='♫ Sound: '+(soundOn?'On':'Off');if(soundOn)beep()});

// Restore a modest amount of unattended production, capped to eight hours.
const elapsed=Math.max(0,Math.min(OFFLINE_CAP,Date.now()-state.last));
if(elapsed>1000){const away=rates().eps*elapsed/1000;gain(away);if(away>0)setTimeout(()=>showToast('While away, the temple gathered '+fmt(away)+' Essence.'),350)}
buildShop();render();save();
let lastTick=Date.now();setInterval(()=>{const now=Date.now(),dt=Math.max(0,Math.min(2,(now-lastTick)/1000));lastTick=now;const passive=rates().eps*dt;if(passive>0){gain(passive);render()}},200);
setInterval(save,10000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save()});window.addEventListener('beforeunload',save);
</script>
</body>
</html>

